// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    StaxLPStaking c;

    function setUp() public {
        vm.prank(0x000000000000000000000000000000000000bEEF, 0x000000000000000000000000000000000000bEEF);
        c = new StaxLPStaking(address(this), address(this));
    }

    function _run(address newDistributor) internal {
        vm.assume(msg.sender != c.owner());
        bool reverted;
        try c.setRewardDistributor(newDistributor) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == true);
    }

    function testFuzz_run(address newDistributor) public {
        vm.assume(uint160(newDistributor) > 255 && newDistributor != address(this) && newDistributor != address(c) && newDistributor != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && newDistributor != 0x000000000000000000636F6e736F6c652e6c6f67 && newDistributor != 0x4e59b44847b379578588920cA78FbF26c0B4956C && newDistributor != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(newDistributor);
    }

    receive() external payable {}
}
